import type{MedusaRequest,MedusaResponse}from'@medusajs/framework/http';import{ContainerRegistrationKeys}from'@medusajs/framework/utils';const aid=(r:any)=>r.auth_context?.actor_id||r.auth_context?.auth_identity_id;async function sid(req:any,a:string){const q=req.scope.resolve(ContainerRegistrationKeys.QUERY)as any;const{data}=await q.graph({entity:'seller_member',fields:['seller.id'],filters:{member_id:a},pagination:{take:1}}).catch(()=>({data:[]}));return data?.[0]?.seller?.id}export async function POST(req:MedusaRequest,res:MedusaResponse){const seller=await sid(req,aid(req)),sp=req.scope.resolve('spike')as any,rows=await sp.listSpikeReturnRequests({id:req.params.id},{take:1}),r=rows[0];if(!r)return res.status(404).json({message:'Return not found'});if(r.seller_id!==seller)return res.status(403).json({message:'هذا المرتجع لا يخص متجرك'});const action=String((req.body as any)?.action||'');if(!['approve','reject'].includes(action))return res.status(422).json({message:'action invalid'});if(action==='reject'&&!String((req.body as any)?.reason||'').trim())return res.status(422).json({message:'سبب الرفض مطلوب'});const updated=await sp.updateSpikeReturnRequests({id:r.id,status:action==='approve'?'approved':'rejected',rejection_reason:action==='reject'?String((req.body as any).reason):null});if(action==='approve'){await sp.createSpikePayables({kind:'customer',beneficiary_id:r.customer_id,order_id:r.order_id,reference_id:r.id,amount:r.amount,currency_code:r.currency_code,status:'pending',note:'مرتجع مقبول — يتم إعادة المبلغ يدويًا للعميل'})}if(r.customer_id)await sp.createSpikeNotifications({audience:'customer',customer_id:r.customer_id,type:'return_'+updated.status,title:action==='approve'?'تم قبول المرتجع':'تم رفض المرتجع',body:action==='approve'?'سيتم التواصل معك لإعادة المبلغ.':String((req.body as any).reason),entity_type:'return',entity_id:r.id,read:false});await sp.createSpikeAuditLogs({actor_id:aid(req),actor_type:'seller',action:'return_'+updated.status,entity_type:'return',entity_id:r.id,note:String((req.body as any)?.reason||'')});res.json({return:updated})}
